def win_rates(df):
    rates = {}
    for rep in sorted(df["Owner"].unique()):
        mine = df[df["Owner"] == rep]
        won = int((mine["Outcome"] == "won").sum())
        lost = int((mine["Outcome"] == "lost").sum())

        # Check if both won and lost counts are greater than zero
        if won > 0 and lost > 0:
            rates[rep] = round(won / (won + lost), 4)
        else:
            rates[rep] = None  # or handle it as needed, e.g., return NaN or a specific value

    return rates

import pandas as pd

def load_export(path):
    try:
        # Attempt to read the CSV with UTF-8 encoding
        df = pd.read_csv(path, encoding="utf-8", dtype=str, keep_default_na=False)
    except UnicodeDecodeError:
        # If UTF-8 decoding fails, try using ISO-8859-1 as a fallback
        df = pd.read_csv(path, encoding="iso-8859-1", dtype=str, keep_default_na=False)

    return df
